def runbook_md(r):
    steps = "\n".join(f"{i}. {s}" for i, s in enumerate(r["steps"], 1))
    return (f"---\ndoc_id: {r['id']}\nversion: {r['v']}\nstatus: {r['status']}\ntitle: {r['title']}\ncategory: {r['cat']}\naccess: {r['access']}\nrecommended_action: {r['op']}\n---\n"
            f"# {r['id']} {r['title']} (version {r['v']}, {r['status']})\n\n## Supported incident types\n{r['types']}\n\n## Preconditions\n{r['pre']}\n\n## Investigation steps\n{steps}\n\n"
            f"## Approved remediation\n{r['rem']}\n\n## Required permission\n{r['perm']}\n\n## Risks and side effects\n{r['risks']}\n\n## Rollback procedure\n{r['rollback']}\n\n"
            f"## Verification criteria\n{r['verify']}\n\n## Escalation\n{r['esc']}\n")
